import{_ as n,C as a,c,o as d,aa as i,G as o}from"./chunks/framework.Cn7WEiMX.js";const g=JSON.parse('{"title":"自定义方块渲染器方块定义","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/defining-a-block-using-a-custom-block-renderer.md","filePath":"wiki/Dynmap/mod-support/defining-a-block-using-a-custom-block-renderer.md"}'),p={name:"wiki/Dynmap/mod-support/defining-a-block-using-a-custom-block-renderer.md"};function r(l,e,m,u,b,h){const t=a("NolebaseGitContributors"),s=a("NolebaseGitChangelog");return d(),c("div",null,[e[0]||(e[0]=i('<h1 id="自定义方块渲染器方块定义" tabindex="-1">自定义方块渲染器方块定义 <a class="header-anchor" href="#自定义方块渲染器方块定义" aria-label="Permalink to &quot;自定义方块渲染器方块定义&quot;">​</a></h1> <p>通过自定义方块渲染器提供的模型定义方块，首先要在模型定义文件里选择并配置渲染器。<code>customblock</code> 设置可以做到，必须包含一或多个方块 ID（用 <code>id</code> 属性设置）、任意所需元数据值（用 <code>data</code> 属性设置）及自定义渲染器的类（用 <code>class</code> 属性设置）。例如，砂岩楼梯方块的定义如下所示：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  customblock:id=128,,data=*,class=org.dynmap.hdmap.renderer.StairBlockRenderer</span></span></code></pre></div><p>除了这些核心属性以外，部分自定义方块渲染器还拥有（且可能需要）额外属性，有时需要正确配置才能正常使用。见对应渲染器的“属性”部分描述了解详情。</p> <p>之后，需要定义自定义渲染器引用的纹理。自定义渲染器描述中的“补丁所需纹理”部分定义了方块所需的 <code>patch&lt;N&gt;</code> 属性。除了这些描述，纹理定义文件内必须包含 <code>block</code> 设置，每个补丁对应 <code>patchN</code> 属性。例如，上述楼梯的这都有渲染器需要 3 个补丁：一个用于方块侧面，一个用于顶面，一个用于底面：对于砂岩楼梯，对应配置为：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  block:id=128,data=*,patch0=0:sandstone_normal,patch1=0:sandstone_top,patch2=0:sandstone_bottom,transparency=SEMITRANSPARENT</span></span></code></pre></div><p>注意：大部分自定义渲染器定义的方块都是不完整或不透明的方块，因此若需要透明属性，则需要在 <code>block</code> 部分预先配置。对于透光方块，需要使用 <code>transparent</code> 设置。对于半透光方块（如台阶和楼梯这类方块）则需要使用 <code>semitransparent</code> 设置。</p> ',12)),o(t),o(s)])}const k=n(p,[["render",r]]);export{g as __pageData,k as default};
